/* Token Radar: warm paper, navy ink, amber rank. No network, no framework. */
:root {
  --paper: #f7f4ee;
  --card: #fffdf9;
  --ink: #1c2733;
  --muted: #5d6b7a;
  --line: #e3ddd0;
  --navy: #14213d;
  --amber: #d97706;
  --amber-soft: #fef3c7;
  --teal: #0f766e;
  --green: #15803d;
  --red: #b91c1c;
  --radius: 12px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 15px/1.55 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.top { background: var(--navy); color: #f8fafc; }
.top-in {
  max-width: 1080px;
  margin: 0 auto;
  padding: 34px 20px 30px;
  display: flex;
  gap: 28px;
  align-items: flex-end;
  justify-content: space-between;
}
.eyebrow {
  margin: 0 0 6px;
  font-size: 12px;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: #94a3b8;
}
.top h1 { margin: 0 0 8px; font-size: 42px; line-height: 1.05; letter-spacing: -.01em; }
.lede { margin: 0; max-width: 640px; color: #cbd5e1; font-size: 16px; }
.top-card {
  background: #1e3a5f;
