.top-card-sub { margin: 2px 0 0; font-size: 13px; color: #cbd5e1; }
main { max-width: 1080px; margin: 0 auto; padding: 20px 20px 40px; }
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}
.stat {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.stat b { display: block; font-size: 26px; line-height: 1.1; }
.stat span { font-size: 12.5px; color: var(--muted); }
.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px 22px;
  margin-bottom: 16px;
}
.panel h2 { margin: 0 0 8px; font-size: 20px; }
.panel h3 { margin: 22px 0 8px; font-size: 16px; }
